INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('fd345954-fc16-4d03-a3b3-7c8bae08e0e2', '21feff02-016d-46e2-bb9d-c27495133b1b', '38. óra: Szorzás tizedes törttel', 'Tizedes tört szorzása egész számmal és tizedes törttel, vesszőhely meghatározása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "ce273a0f-7ce3-414c-adac-18af7c8f3ce4", "text": "Hogyan határozzuk meg a tizedesjegyek számát két tizedes tört szorzatában?", "type": "multiple-choice", "options": [{"id": "0fd5f0b5-47cb-4f7d-8717-dde786b5c697", "text": "A tényezők tizedesjegyeinek számát összeadjuk", "isCorrect": true}, {"id": "3527fe4d-67dd-4b1c-842a-ccf9503cd030", "text": "A nagyobbik tényező tizedesjegyeit vesszük", "isCorrect": false}, {"id": "938ee9ae-f36b-4a0e-98e3-38b27118d90b", "text": "Mindig 1 tizedesjegy lesz", "isCorrect": false}, {"id": "96247996-d1c0-4672-828b-3e8d86f17b01", "text": "Nem lesz tizedesjegy", "isCorrect": false}], "timeLimit": 15}, {"id": "8eca5724-9278-4330-8db8-b2b24fb907e6", "text": "Mennyi 0,3 * 0,2? (3*2 = 6, 2 tizedesjegy)", "type": "multiple-choice", "options": [{"id": "109b50dd-033e-4e1d-8581-0e5ee3fba553", "text": "0,06", "isCorrect": true}, {"id": "74eac763-d078-431c-847d-d6c7210043b3", "text": "0,6", "isCorrect": false}, {"id": "7f6ad6e3-60e1-491a-950f-94fcd24ba8b8", "text": "6,0", "isCorrect": false}, {"id": "067fac1b-aafe-477d-9e05-4ee6ea5ae57f", "text": "0,006", "isCorrect": false}], "timeLimit": 15}, {"id": "49edf83f-379e-4c73-9628-007251400cb3", "text": "Mennyi 2,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "7d85f8f1-ccfc-4ab9-9043-33ac3e085b8f", "text": "Mennyi 1,2 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "58c6b71b-7925-4086-ad0c-742647a73c51", "text": "Ha egy tizedes törtet 10-zel szorzunk, a tizedesvessző egy hellyel jobbra lép.", "type": "true-false", "options": [{"id": "00f024c3-9000-4cb7-80ed-1fdd39efa4ec", "text": "Igaz", "isCorrect": true}, {"id": "711cae91-8d7b-4f41-94f8-bca10dfd7dd5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8bf1549a-1097-430d-a7f9-8f7d8c69d789", "text": "Mennyi 3,45 * 100?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "345"}, {"id": "7e4a1aaa-dcce-4c77-9ef0-15ea990fe38a", "text": "Mennyi 0,1 * 0,1?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.01"}]'::jsonb, true, NOW()),
('92fe7d6a-11c4-4b75-925d-bba4ce6fff55', '21feff02-016d-46e2-bb9d-c27495133b1b', '39. óra: Osztás tizedes törttel', 'Tizedes törttel való osztás szabálya, osztó egész számmá alakítása (bővítés 10-zel, 100-zal).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "981ba0c2-4270-49b7-a98c-bde0d979b67e", "text": "Mit teszünk tizedes törttel való osztáskor először?", "type": "multiple-choice", "options": [{"id": "66a81980-7f46-465a-a11e-a05493bb8e5c", "text": "Az osztandót és az osztót is megszorozzuk 10-zel/100-zal, hogy az osztó egész szám legyen", "isCorrect": true}, {"id": "c69bdbeb-eb5c-4696-8fdd-0f48fd35d1fc", "text": "Elhagyjuk a tizedesvesszőt az osztandóból", "isCorrect": false}, {"id": "104e1011-dc6a-46e6-8d7e-a6d01ddad004", "text": "Kivonjuk az osztót az osztandóból", "isCorrect": false}, {"id": "57cb381f-4c3b-4d3c-b602-0bf9b90bac21", "text": "Csak az osztót szorozzuk meg", "isCorrect": false}], "timeLimit": 15}, {"id": "26a1b3a7-2213-4e7c-8c2c-ca0cec403d0d", "text": "Mennyi 2,4 : 0,6? (24 : 6)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "bf515114-af9a-460c-adb4-a8573e62efe5", "text": "Mennyi 1,5 : 0,3? (15 : 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "29b84268-1a8c-4ccd-8a72-7382f3d03aee", "text": "Ha egy tizedes törtet 10-zel osztunk, a tizedesvessző 1 hellyel balra lép.", "type": "true-false", "options": [{"id": "bf5076a5-8a0b-48a8-864a-5d7ae20fa354", "text": "Igaz", "isCorrect": true}, {"id": "cbb0eb3d-a3a5-4681-b2d0-2ea3d3aa4e6b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "963366d6-5c1b-490c-9126-98d72b511d42", "text": "Mennyi 45,6 : 10?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.56"}, {"id": "01c09205-1edd-4418-a2df-3459d2ddf744", "text": "Mennyi 3,6 : 0,1? (36 : 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "8f976878-cfe5-4c67-9e33-b2f30f6bed52", "text": "A tizedes törttel való osztást ellenőrizhetjük szorzással.", "type": "true-false", "options": [{"id": "6a5d14e3-762d-4e01-a4df-3ffda9ac5385", "text": "Igaz", "isCorrect": true}, {"id": "a9b07250-519f-4497-9af6-4aba31eaec7a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('edb4cfc1-d518-411c-82ff-42281995e945', '21feff02-016d-46e2-bb9d-c27495133b1b', '40. óra: Hétköznapi problémák megoldása tizedes törtek szorzásának, osztásának felhasználásával', 'Vásárlási, mértékegységes és szöveges feladatok.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "9beb8ab8-0326-4024-85f2-655851ed427e", "text": "1 kg sajt ára 3200 Ft. Mennyibe kerül 0,5 kg sajt? (3200 * 0,5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1600"}, {"id": "115ae580-a19b-4ab5-92e7-c8e18b8e36e8", "text": "Peti 3,5 kg almát vett 400 Ft/kg áron. Hány Ft-ot fizetett?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1400"}, {"id": "7ce15794-72ff-41cb-a260-4a8fbfeb3d1c", "text": "Egy 4,8 méteres lécet 4 egyenlő darabra vágunk. Hány méter egy darab?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "af2b821c-d9f6-4f8f-b688-f95e1eeb3eb2", "text": "Ha 0,25 liter üdítő 150 Ft, akkor 1 liter üdítő (4 * 0,25) 600 Ft-ba kerül.", "type": "true-false", "options": [{"id": "07b85fc7-f895-4f67-8eb4-69ec6e8ff87e", "text": "Igaz", "isCorrect": true}, {"id": "b97524a6-8f4f-4cce-b6d9-048917d028fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d6c72ae7-d016-437a-844a-5b323b9773e5", "text": "Hány liter benzin fér a tankba 12000 Ft-ért, ha 1 liter benzin 600 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "7a2b46be-f312-4b0f-81fa-25390d9aa9b8", "text": "A becslés segít ellenőrizni, hogy a tizedesvesszőt jó helyre tettük-e a végeredményben.", "type": "true-false", "options": [{"id": "dea1869b-40f3-4e91-ba07-517cfd1ff5e4", "text": "Igaz", "isCorrect": true}, {"id": "2c8e6191-095a-43da-9979-638ec1091eb9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9ed521de-5fe4-4f7e-ba2e-eea18a1fd7e8", "text": "Mennyi 1,5 kg narancs ára, ha 1 kg 800 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}]'::jsonb, true, NOW()),
('8b0391e3-b58a-40df-8b1b-9b92982e1f3d', '21feff02-016d-46e2-bb9d-c27495133b1b', '41. óra: Összetett műveletek, zárójelfelbontás', 'Műveleti sorrend, zárójelezés szabályai tizedes és közönséges törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "f7e43df1-6869-4ffd-8bf1-4e5866d4d63e", "text": "Mi a helyes műveleti sorrend?", "type": "multiple-choice", "options": [{"id": "de8ad54c-b1f3-4b1e-b285-849b20efe79e", "text": "Zárójelben lévő műveletek -> szorzás/osztás balról jobbra -> összeadás/kivonás balról jobbra", "isCorrect": true}, {"id": "4136c452-edf8-440d-8234-e31154b10a11", "text": "Mindig összeadással kezdünk", "isCorrect": false}, {"id": "08e026e8-fc4f-464a-98e7-4133b1e45b69", "text": "Balról jobbra haladunk művelet típustól függetlenül", "isCorrect": false}, {"id": "d112d652-8e35-4ecf-98ec-001f9c8ce795", "text": "Kivonással kezdünk", "isCorrect": false}], "timeLimit": 15}, {"id": "f8dbee2e-4ed8-49a5-90bf-49f8178afb5f", "text": "Mennyi 2 + 3 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "2204e30b-3de9-4399-af4f-af17aff195b4", "text": "Mennyi (2 + 3) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "447153e2-4fd8-4665-a1df-9e3e935f4abf", "text": "Mennyi 10 - 2 * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "b04ec5a9-7d45-4d9a-bc68-25121f236850", "text": "A zárójel megváltoztatja a műveletek elvégzésének megszokott sorrendjét.", "type": "true-false", "options": [{"id": "90b7e50e-ca6f-47c0-b9f5-8a9aebfae0de", "text": "Igaz", "isCorrect": true}, {"id": "6e2f9e4e-36b8-4d97-a272-be135d180884", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6127d410-03ec-47c3-bc6b-3c9056b47022", "text": "Mennyi 0,5 + 0,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "588ed8e4-31cc-4da9-89fd-b4af5fda3727", "text": "Mennyi (0,5 + 0,5) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()),
('a8d7c6ba-af25-46c5-b44a-9437bb3194c9', '21feff02-016d-46e2-bb9d-c27495133b1b', '42. óra: Összetett műveletek, zárójelfelbontás gyakorlása', 'Gyakorlás feladatlapok és összetett kifejezések segítségével.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "0d5c15de-c8c6-4663-9bba-bf777f840301", "text": "Mennyi 100 - (20 + 30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "e6ba8b1e-2ef8-41fb-a946-879de8de503a", "text": "Mennyi 15 : 3 + 2 * 5? (5 + 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "82a34a9a-fc26-43cd-be9b-df96f5ea9fa3", "text": "Mennyi 0,2 * 5 + 0,8 : 2? (1 + 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.4"}, {"id": "d3467eec-8ebc-4cf2-8ef8-3418f8d9ee6d", "text": "A szorzás és az osztás egyenrangú műveletek, elvégzésük balról jobbra haladva történik.", "type": "true-false", "options": [{"id": "56177327-0db1-4305-b3fc-33d107ff7b3f", "text": "Igaz", "isCorrect": true}, {"id": "ad55eb52-145f-46e0-8f22-79fcd24c4e8e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ca23274a-0126-4522-9a9f-08991d769763", "text": "Mennyi (1,2 + 0,8) * (3,5 - 1,5)? (2 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "7a31c5af-f057-4ae6-8690-00baf33928b8", "text": "Ha a zárójel előtt minusz jel áll, a zárójel elhagyásakor a bent lévő tagok előjele az ellenkezőjére vált.", "type": "true-false", "options": [{"id": "64b3bdec-952b-4882-923f-dcebb30f8566", "text": "Igaz", "isCorrect": true}, {"id": "d821faa9-fe08-48d6-8d57-8f327110f7bf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e3f3ccfc-8ac5-4722-a843-a23db7a09063", "text": "Mennyi 50 - 5 * 8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('9afdd9c7-4d0a-4439-8191-91d48b401dc1', '21feff02-016d-46e2-bb9d-c27495133b1b', '43. óra: Összefoglalás', 'A törtekről tanultak ismétlése, rendszerezése, algoritmusos gondolkodás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "5b26d2d6-d4ba-49ac-bccd-07ed8f54dd61", "text": "Mennyi 3/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "731d1072-b5ee-4b67-8532-ec853def4946", "text": "3/5", "isCorrect": true}, {"id": "abd903ce-316b-4240-9957-7f367cedb72e", "text": "12/20", "isCorrect": false}, {"id": "8c481fa7-d7d3-45aa-8f9b-041b3493eea4", "text": "7/9", "isCorrect": false}, {"id": "172902e8-8b35-49d6-bf63-b6f46c756293", "text": "4/5", "isCorrect": false}], "timeLimit": 15}, {"id": "acf3a025-68c7-45f8-9721-2f05971ff6f6", "text": "Mennyi 1/2 : 1/3? (1/2 * 3/1)", "type": "multiple-choice", "options": [{"id": "86dc4782-078e-429e-b931-03f7440908f7", "text": "3/2 (1,5)", "isCorrect": true}, {"id": "f61720bc-417a-471d-b491-d83c4d269cd3", "text": "1/6", "isCorrect": false}, {"id": "cc9fee20-c25f-429c-b189-517c0b0fdf10", "text": "2/3", "isCorrect": false}, {"id": "5e2ce1c1-4a92-4489-88b4-712322eae6e9", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "3764c7e2-0b47-4170-98cb-22ab452ef0aa", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "2b2a14fb-60d8-427c-beb5-d2108076b214", "text": "Mennyi 6,4 : 0,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "cd7de4b6-8665-4d96-b858-a0657ea2c0fa", "text": "A 0,75 megegyezik a 3/4 közönséges tört értékével.", "type": "true-false", "options": [{"id": "0691a963-4e75-450a-85fc-d0f07e0e353f", "text": "Igaz", "isCorrect": true}, {"id": "77ab7f4c-20bb-456c-9c30-0b11ce832870", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6341f80a-e701-4e4f-abc6-be8c0a3a032c", "text": "Mennyi 50-nek a 40%-a (vagy 2/5 része)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "6ed5dada-a195-4ac3-994b-69c7300ca8ee", "text": "Melyik szám reciproka 0,5 (azaz 1/2)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()),
('8c5402f8-f56e-44fa-b50e-af5db34560e1', '21feff02-016d-46e2-bb9d-c27495133b1b', '44. óra: Feladatmegoldás', 'Gyakorló feladatok megbeszélése egyéni és csoportmunkában.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "db638e32-8a41-44bc-b856-93c5e1f2b304", "text": "Mennyi 0,75 + 1/4? (0,75 + 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "bf4b7373-57ce-4efb-8189-800856ad6558", "text": "Mennyi 1,5 - 3/4? (1,5 - 0,75)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.75"}, {"id": "c1240854-40fb-4e32-83e8-0bf86f2eb01a", "text": "Peti elköltötte a pénze 2/5-ét, majd a maradék 1/2-ét. A pénze hányadrésze maradt meg?", "type": "multiple-choice", "options": [{"id": "c294e208-c6d5-4c5e-a054-cd40b271f5f4", "text": "3/10 (azaz 30%-a)", "isCorrect": true}, {"id": "47b15202-927a-4071-bb69-767bbb30002f", "text": "1/5", "isCorrect": false}, {"id": "3fc30bdc-2226-4c81-b20f-25ee8716c4a0", "text": "1/2", "isCorrect": false}, {"id": "5b9526f8-f670-4c13-82d6-c151c25cb999", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "2d33aebe-28c4-4d8c-ba16-5de80f612193", "text": "Ha a számláló és a nevező megegyezik, a tört értéke 1.", "type": "true-false", "options": [{"id": "7f1c8dd6-a0d1-4398-9793-7232453554af", "text": "Igaz", "isCorrect": true}, {"id": "435c45cb-d06d-4d85-8c6d-1e499dc717db", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "475f365b-1775-4a50-b19d-5cddd95b4cfc", "text": "Mennyi 0,8 * 2,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "c6ab0795-050e-4615-b55c-a706298c9bfc", "text": "Mennyi 9 : 0,3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "90d59d01-9e8e-4901-a288-fdbffcd43017", "text": "A 0,125 megegyezik az 1/8 tört értékével.", "type": "true-false", "options": [{"id": "c5529501-9def-46b2-b239-3fb1ddcebb91", "text": "Igaz", "isCorrect": true}, {"id": "cf1eb028-5d70-486d-8e2f-ce1e25119f10", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('f4a13154-b124-4723-b7d1-f4b172436407', '21feff02-016d-46e2-bb9d-c27495133b1b', '45. óra: Játékos feladatok törtekkel', 'Társasjáték törtekkel, folyamatos tanári ellenőrzés és hibajavítás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "d9ee5155-e495-4dbe-9d7b-ce81e40286ba", "text": "Melyik tört azonos értékű 4/12-vel?", "type": "multiple-choice", "options": [{"id": "63afb5b5-2213-4ad6-9211-2389eb67e8f5", "text": "1/3", "isCorrect": true}, {"id": "9dfb5ad2-cbfc-4bf2-8e15-4c005051d22f", "text": "1/4", "isCorrect": false}, {"id": "f9629f66-897d-43a9-88e1-95e21e3c6736", "text": "2/3", "isCorrect": false}, {"id": "15f1371e-716b-4585-aa54-d10bdd68eff7", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "2a070ca3-98f7-4c4b-8ee4-3fa86a06d8dd", "text": "Melyik tört azonos értékű 5/20-szal?", "type": "multiple-choice", "options": [{"id": "d3f48c75-9871-4b99-a689-a694ccb7565d", "text": "1/4", "isCorrect": true}, {"id": "163b9b27-ce64-47bb-bd95-bf0f7f1649f3", "text": "1/5", "isCorrect": false}, {"id": "84ddc68d-57ff-4a2a-a901-eded4c9ff988", "text": "2/5", "isCorrect": false}, {"id": "f0e71d31-3677-4a5c-81ac-5fb6706a3983", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "1e89bbe5-8b46-45e4-a72e-1f4e0ee5d93b", "text": "Mennyi 0,6 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.3"}, {"id": "7e190009-fad6-4277-8268-8ceb51832a3b", "text": "Mennyi 0,4 : 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "4d3ff515-4622-443d-a719-e1524a7db202", "text": "A 0,5 nagyobb, mint a 0,45.", "type": "true-false", "options": [{"id": "892e0616-8467-4fcc-a8d8-33b752021687", "text": "Igaz (0,50 > 0,45)", "isCorrect": true}, {"id": "daccec17-fb33-4984-bb1e-ca09ef848347", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "05f9a560-e124-4131-9e35-75a6eca33deb", "text": "Hány század van 0,3-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "ced386f1-f12c-4ad0-ae54-2e359e1db1f9", "text": "A törtek átírása tizedes tört alakba megkönnyíti az összehasonlítást.", "type": "true-false", "options": [{"id": "23dcf265-8f9c-4f94-8627-3e633635cd68", "text": "Igaz", "isCorrect": true}, {"id": "5f5322cf-2b1d-420c-9575-000e5f6598b4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('77c94b1d-3e5c-41cd-aecd-af5835a670d6', '21feff02-016d-46e2-bb9d-c27495133b1b', '46. óra: Témazáró dolgozat', 'Témazáró számonkérés a Törtek fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "31a8baf0-9d3f-402c-aca1-367bf5ef2a67", "text": "1. Mennyi 2/3 + 1/6? (4/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "47b523c5-39f3-430f-9d01-60e3facc4ca6", "text": "5/6", "isCorrect": true}, {"id": "a053dbc0-929b-4709-b570-5bb9115c6528", "text": "3/9", "isCorrect": false}, {"id": "2ef1fafa-30f8-4cfb-b99f-ecc2dc9038a6", "text": "3/6", "isCorrect": false}, {"id": "8b407779-61cc-40da-bb39-ba9116f51f9f", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "c931008e-8a79-4ff3-aaad-ebb24433b0fc", "text": "2. Mennyi 3/5 * 5/6?", "type": "multiple-choice", "options": [{"id": "e7560fc9-d64a-4470-a471-9c682a5edb32", "text": "15/30 (azaz 1/2)", "isCorrect": true}, {"id": "29e9e7d0-daac-4e20-a5ac-cb21b62f1e37", "text": "8/11", "isCorrect": false}, {"id": "a1f8a850-4767-46e2-9728-b776d9978e01", "text": "15/11", "isCorrect": false}, {"id": "6c27d096-9644-40b5-9ed9-18261ddf0d86", "text": "3/6", "isCorrect": false}], "timeLimit": 15}, {"id": "4a44b495-65be-40e3-8bc7-3a4ac1dc7c68", "text": "3. Mennyi 3/4 : 1/2? (3/4 * 2/1)", "type": "multiple-choice", "options": [{"id": "094825cd-bab7-4e6e-8db4-f4187cd15380", "text": "6/4 (azaz 3/2 vagy 1,5)", "isCorrect": true}, {"id": "183a2947-3fb9-47a0-b5c9-435f2f7f914b", "text": "3/8", "isCorrect": false}, {"id": "e83d0e9f-cb8c-4c67-b5c7-09358c07dfeb", "text": "1/4", "isCorrect": false}, {"id": "189ef31c-65cd-449a-baf2-f1d944746cfa", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "46e28623-bf24-41e0-a858-55f2bc1c9a29", "text": "4. Mi a 4/9 reciproka?", "type": "multiple-choice", "options": [{"id": "cd61db63-a809-4b10-9165-729beb07d052", "text": "9/4", "isCorrect": true}, {"id": "7bf10273-5e01-4cfd-9d8f-c613e87e8c71", "text": "-4/9", "isCorrect": false}, {"id": "247d1782-af32-428e-aad1-9b3a53565839", "text": "1/4", "isCorrect": false}, {"id": "ada62127-3acf-41f1-847c-90a0799688ed", "text": "4/9", "isCorrect": false}], "timeLimit": 15}, {"id": "136e2b1f-1118-4e9d-bd6b-3fdbc453e97c", "text": "5. Mennyi 2,4 + 3,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6.2"}, {"id": "c9e5af87-9207-4d28-a6ea-1bd938bb0048", "text": "6. Mennyi 1,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "574f111b-ccc2-4cb2-8d2c-2763696114cd", "text": "7. Mennyi 4,2 : 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "e3901c8c-1e8d-455c-83ce-4ed7be8ea046", "text": "8. Mennyi 60-nak a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "b64e84b6-7c4e-4799-928b-be9800a7594e", "text": "9. A 0,25 megegyezik az 1/4 törttel.", "type": "true-false", "options": [{"id": "b6b9f9dd-3040-4263-a0a7-6ab7209c7b10", "text": "Igaz", "isCorrect": true}, {"id": "8f119479-e373-498e-9bd6-2217f0b67726", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "aba03aa3-e117-4fa7-bb8e-7c3a4741efea", "text": "10. Mennyi (1,5 + 0,5) * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()),
('d81bdcd5-53fc-40af-8668-06295c09236d', '21feff02-016d-46e2-bb9d-c27495133b1b', '47. óra: Témazáró dolgozat értékelése', 'A dolgozat megbeszélése, a törtek műveleteinek összefoglaló értékelése.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "f8cb65d7-45d8-4821-939f-ce880e2d4e79", "text": "Mi a leggyakoribb hiba a törtek osztásakor?", "type": "multiple-choice", "options": [{"id": "0b33be3c-e9fe-423e-bde7-f46782886593", "text": "Az osztó reciprokával való szorzás elfelejtése", "isCorrect": true}, {"id": "c113efdf-591e-4895-8f8f-0f0951115f56", "text": "A számlálók leírása", "isCorrect": false}, {"id": "10fb1dfa-3139-4381-a7df-3d3f78b71faf", "text": "A zárójel használata", "isCorrect": false}, {"id": "ed1c89f9-7aaf-4af0-aa9a-6e4d505859f3", "text": "A művelet elvégzése", "isCorrect": false}], "timeLimit": 15}, {"id": "0d7ecd60-c1f5-44e9-ba03-f9aca3795688", "text": "Tizedes törtek osztásakor az osztónak egész számnak kell lennie a művelet elvégzése előtt.", "type": "true-false", "options": [{"id": "143ed23d-6131-4e7a-8c72-ace465cd532c", "text": "Igaz", "isCorrect": true}, {"id": "a9c4b70c-18e3-42cd-bc34-91ddee0f5f88", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7a8f3b4d-1f95-4dee-94f6-211dbdab6e8f", "text": "Mennyi 1/2 * 4/5?", "type": "multiple-choice", "options": [{"id": "f2bfb529-3842-4952-bd59-02fcf0c295cc", "text": "2/5", "isCorrect": true}, {"id": "fea5bf83-a430-4900-9f76-3b181d640a64", "text": "4/10", "isCorrect": false}, {"id": "7e49ba9b-f71d-43bf-b32a-7e43e09b440c", "text": "1/5", "isCorrect": false}, {"id": "0ad77228-e32e-4efc-93b5-1059e2552738", "text": "5/7", "isCorrect": false}], "timeLimit": 15}, {"id": "450c5009-52a0-40ef-a047-c61f7154aeb5", "text": "Mennyi 2,5 : 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "0c8c2e16-7bb6-4847-a878-4b10a9cf213b", "text": "A gyakorlás és a hibák javítása segít a jobb teljesítmény elérésében.", "type": "true-false", "options": [{"id": "6635feb2-d3af-4ac1-96